@RunWith(AndroidJUnit4.class)
public class ViewedFileJourneysTest {
    private Context context(){return InstrumentationRegistry.getInstrumentation().getTargetContext();}
    private byte[] zip(Map<String,String> files)throws Exception{ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(ZipOutputStream zip=new ZipOutputStream(bytes)){for(Map.Entry<String,String> file:files.entrySet()){zip.putNextEntry(new ZipEntry(file.getKey()));zip.write(file.getValue().getBytes(StandardCharsets.UTF_8));zip.closeEntry();}}return bytes.toByteArray();}
    private byte[] wordArchive(Map<String,byte[]> files)throws Exception{ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(ZipOutputStream zip=new ZipOutputStream(bytes)){for(Map.Entry<String,byte[]> file:files.entrySet()){zip.putNextEntry(new ZipEntry(file.getKey()));zip.write(file.getValue());zip.closeEntry();}}return bytes.toByteArray();}
    @Test public void spreadsheetControlsLeaveAFullDataRowVisibleWithLongNamesAndCurrentFontScale()throws Exception{
        android.app.Instrumentation instrument=InstrumentationRegistry.getInstrumentation();android.app.Activity activity=instrument.startActivitySync(new Intent(context(),app.space.notes.NotesActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));java.util.concurrent.atomic.AtomicReference<SpreadsheetPreview> shown=new java.util.concurrent.atomic.AtomicReference<>();
        NotesHost host=new NotesHost(){public void showMessage(String s){}public void shareText(String a,String b){}public void chooseLocalFolder(){}public void openExistingFolder(){}public void exportBackup(){}public void importBackup(){}public String versionLabel(){return "Synthetic spreadsheet viewport";}};
        try{SpreadsheetFile book=SpreadsheetFile.csv("Name,Value\nVisible row,भारत ಕನ್ನಡ 😀\nAnother row,2");StringBuilder name=new StringBuilder("Synthetic-");for(int i=0;i<180;i++)name.append('x');name.append(".csv");instrument.runOnMainSync(()->{NotesDesign design=new NotesDesign(activity,false);android.widget.LinearLayout parent=new android.widget.LinearLayout(activity);parent.setOrientation(android.widget.LinearLayout.VERTICAL);android.widget.TextView heading=design.label("Synthetic spreadsheet preview",18,design.ink);heading.setMinHeight(design.dp(56));parent.addView(heading);SpreadsheetPreview view=new SpreadsheetPreview(activity,design,book,host,Uri.parse("content://com.android.externalstorage.documents/document/primary%3Asynthetic.csv"),name.toString());shown.set(view);parent.addView(view,new android.widget.LinearLayout.LayoutParams(-1,0,1));activity.setContentView(parent);});
            java.util.concurrent.CountDownLatch frames=new java.util.concurrent.CountDownLatch(1);instrument.runOnMainSync(()->shown.get().postOnAnimation(()->shown.get().postOnAnimation(frames::countDown)));assertTrue(frames.await(15,java.util.concurrent.TimeUnit.SECONDS));instrument.waitForIdleSync();instrument.runOnMainSync(()->{android.widget.HorizontalScrollView grid=null;for(int i=0;i<shown.get().getChildCount();i++)if(shown.get().getChildAt(i) instanceof android.widget.HorizontalScrollView)grid=(android.widget.HorizontalScrollView)shown.get().getChildAt(i);assertNotNull(grid);android.widget.LinearLayout column=(android.widget.LinearLayout)grid.getChildAt(0);androidx.recyclerview.widget.RecyclerView rows=(androidx.recyclerview.widget.RecyclerView)column.getChildAt(1);assertNotNull("A real data row must be laid out, not hidden behind controls",rows.getChildAt(0));assertTrue("Heading plus at least one complete data row must fit",grid.getHeight()>=column.getChildAt(0).getHeight()+rows.getChildAt(0).getHeight());});
            android.graphics.Bitmap shot=instrument.getUiAutomation().takeScreenshot();assertNotNull(shot);try{File directory=new File(context().getFilesDir(),"ux-review");assertTrue(directory.isDirectory() || directory.mkdirs());try(OutputStream out=new FileOutputStream(new File(directory,"spreadsheet-grid-viewport.png"))){assertTrue(shot.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out));}}finally{shot.recycle();}
        }finally{instrument.runOnMainSync(()->{if(shown.get()!=null)shown.get().close();activity.finish();});}
    }
    @Test public void wordPreparedPagesKeepStoredBreaksHeaderLogoAndOriginalBytes()throws Exception{
        String ns=" xmlns:w=\"http://schemas.openxmlformats.org/wordprocessingml/2006/main\" xmlns:r=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships\" xmlns:a=\"http://schemas.openxmlformats.org/drawingml/2006/main\" xmlns:wp=\"http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing\"";
        Map<String,byte[]> files=new LinkedHashMap<>();files.put("word/document.xml",("<w:document"+ns+"><w:body><w:p><w:r><w:t>First prepared page</w:t></w:r></w:p><w:p><w:r><w:br w:type=\"page\"/><w:t>Second prepared page ಭಾರತ 😀</w:t></w:r></w:p><w:sectPr><w:pgSz w:w=\"11900\" w:h=\"16840\"/><w:headerReference w:type=\"default\" r:id=\"head\"/></w:sectPr></w:body></w:document>").getBytes(StandardCharsets.UTF_8));
        files.put("word/_rels/document.xml.rels","<Relationships><Relationship Id=\"head\" Target=\"header1.xml\"/></Relationships>".getBytes(StandardCharsets.UTF_8));
        files.put("word/header1.xml",("<w:hdr"+ns+"><w:p><w:r><w:t>Company heading</w:t></w:r></w:p><w:p><w:r><w:drawing><wp:inline><wp:extent cx=\"1270000\" cy=\"423333\"/><a:graphic><a:blip r:embed=\"logo\"/></a:graphic></wp:inline></w:drawing></w:r></w:p></w:hdr>").getBytes(StandardCharsets.UTF_8));files.put("word/_rels/header1.xml.rels","<Relationships><Relationship Id=\"logo\" Target=\"media/logo.png\"/></Relationships>".getBytes(StandardCharsets.UTF_8));
        android.graphics.Bitmap logo=android.graphics.Bitmap.createBitmap(60,20,android.graphics.Bitmap.Config.ARGB_8888);logo.eraseColor(android.graphics.Color.RED);ByteArrayOutputStream png=new ByteArrayOutputStream();assertTrue(logo.compress(android.graphics.Bitmap.CompressFormat.PNG,100,png));logo.recycle();files.put("word/media/logo.png",png.toByteArray());
        File original=File.createTempFile("original-word-pages-",".docx",context().getCacheDir());byte[] bytes=wordArchive(files);java.nio.file.Files.write(original.toPath(),bytes);WordPageFile.Result result=null;
        try{result=WordPageFile.preview(context(),bytes);assertEquals(2,result.pdf.ratios.length);assertTrue(result.text,result.text.contains("Company heading"));assertTrue(result.text.contains("Second prepared page"));assertTrue(result.details.contains("Approximate pagination"));assertTrue(result.pdf.text(1),result.pdf.text(1).contains("Second prepared page ಭಾರತ 😀"));
            try(android.graphics.pdf.PdfRenderer.Page page=result.pdf.renderer.openPage(0)){assertEquals(595,page.getWidth());assertEquals(842,page.getHeight());android.graphics.Bitmap rendered=android.graphics.Bitmap.createBitmap(595,842,android.graphics.Bitmap.Config.ARGB_8888);try{page.render(rendered,null,null,android.graphics.pdf.PdfRenderer.Page.RENDER_MODE_FOR_DISPLAY);int red=0;for(int y=0;y<842;y+=2)for(int x=0;x<595;x+=2){int pixel=rendered.getPixel(x,y);if(android.graphics.Color.red(pixel)>200 && android.graphics.Color.green(pixel)<60 && android.graphics.Color.blue(pixel)<60)red++;}assertTrue("Header logo must actually render, not just parse",red>100);File directory=new File(context().getFilesDir(),"ux-review");assertTrue(directory.isDirectory() || directory.mkdirs());try(OutputStream out=new FileOutputStream(new File(directory,"word-synthetic-paper-page.png"))){assertTrue(rendered.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out));}}finally{rendered.recycle();}}
            assertArrayEquals(bytes,java.nio.file.Files.readAllBytes(original.toPath()));
        }finally{if(result!=null){result.pdf.closeText();result.pdf.close();assertFalse(result.pdf.temporary.exists());}original.delete();}
    }
    @Test public void wordPagePreviewRejectsEntitiesAndArchiveTraversal()throws Exception{
        Map<String,byte[]> invalid=new LinkedHashMap<>();invalid.put("word/document.xml","<unrelated-xml/>".getBytes(StandardCharsets.UTF_8));try{WordPageFile.Result unexpected=WordPageFile.preview(context(),wordArchive(invalid));unexpected.pdf.closeText();unexpected.pdf.close();fail("Do not present unrelated XML as a successful blank Word preview");}catch(IOException expected){assertTrue(expected.getMessage().contains("Word document body"));}
        for(String name:new String[]{"word/document.xml","../word/document.xml"}){Map<String,byte[]> files=new LinkedHashMap<>();files.put(name,"<!DOCTYPE document [<!ENTITY x SYSTEM 'file:///private'>]><document>&x;</document>".getBytes(StandardCharsets.UTF_8));try{WordPageFile.Result unexpected=WordPageFile.preview(context(),wordArchive(files));unexpected.pdf.closeText();unexpected.pdf.close();fail("Unsafe Word source accepted");}catch(IOException expected){assertNotNull(expected.getMessage());}}
    }
    @Test public void continuousPdfHasVerticalRecyclerAndOfflineTextWithoutTouchingOriginal()throws Exception{
        File original=File.createTempFile("original-synthetic-pdf-",".pdf",context().getCacheDir()),copy=File.createTempFile("viewed-synthetic-pdf-",".pdf",context().getCacheDir());LocalPdfPreview.Document document=null;
        try{
            android.graphics.pdf.PdfDocument generated=new android.graphics.pdf.PdfDocument();try{
                for(int page=1;page<=3;page++){android.graphics.pdf.PdfDocument.Page p=generated.startPage(new android.graphics.pdf.PdfDocument.PageInfo.Builder(600,800,page).create());android.graphics.Paint paint=new android.graphics.Paint();paint.setTextSize(24);p.getCanvas().drawText("Synthetic PDF page "+page,40,80,paint);generated.finishPage(p);}try(OutputStream out=new FileOutputStream(original)){generated.writeTo(out);}
            }finally{generated.close();}
            byte[] before=java.nio.file.Files.readAllBytes(original.toPath());java.nio.file.Files.write(copy.toPath(),before);com.tom_roush.pdfbox.android.PDFBoxResourceLoader.init(context());document=new LocalPdfPreview.Document(copy);assertEquals(3,document.ratios.length);assertTrue(document.text(1),document.text(1).contains("Synthetic"));
            final LocalPdfPreview.Document owned=document;InstrumentationRegistry.getInstrumentation().runOnMainSync(()->{LocalPdfPreview view=new LocalPdfPreview(context(),new NotesDesign(context(),false),owned);androidx.recyclerview.widget.RecyclerView pages=null;for(int i=0;i<view.getChildCount();i++)if(view.getChildAt(i) instanceof androidx.recyclerview.widget.RecyclerView)pages=(androidx.recyclerview.widget.RecyclerView)view.getChildAt(i);assertNotNull(pages);assertEquals(3,pages.getAdapter().getItemCount());assertEquals(androidx.recyclerview.widget.RecyclerView.VERTICAL,((androidx.recyclerview.widget.LinearLayoutManager)pages.getLayoutManager()).getOrientation());view.close();});document=null;
            long until=android.os.SystemClock.elapsedRealtime()+5000;while(copy.exists() && android.os.SystemClock.elapsedRealtime()<until)Thread.sleep(20);assertFalse("Both renderer and text owners must release their temporary file",copy.exists());assertArrayEquals(before,java.nio.file.Files.readAllBytes(original.toPath()));
        }finally{if(document!=null){document.closeText();document.close();}copy.delete();original.delete();}
    }
    @Test public void spreadsheetBeyondEditorLimitKeepsWorkbookOrderAndSparsePositions()throws Exception{
        Map<String,String> files=new LinkedHashMap<>();files.put("xl/workbook.xml","<workbook xmlns:r=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships\"><sheets><sheet name=\"First visible\" r:id=\"r2\"/><sheet name=\"Large\" r:id=\"r1\"/></sheets></workbook>");
        files.put("xl/_rels/workbook.xml.rels","<Relationships><Relationship Id=\"r1\" Target=\"worksheets/sheet1.xml\"/><Relationship Id=\"r2\" Target=\"worksheets/sheet2.xml\"/></Relationships>");
        files.put("xl/worksheets/sheet2.xml","<worksheet><sheetData><row r=\"2\"><c r=\"C2\" t=\"inlineStr\"><is><t>भारत ಭಾರತ</t></is></c></row></sheetData></worksheet>");
        StringBuilder large=new StringBuilder("<worksheet><sheetData>");for(int row=1;row<=600;row++){large.append("<row r=\"").append(row).append("\"><c r=\"A").append(row).append("\" t=\"inlineStr\"><is><t>");for(int n=0;n<220;n++)large.append('x');large.append("</t></is></c></row>");}large.append("</sheetData></worksheet>");files.put("xl/worksheets/sheet1.xml",large.toString());
        SpreadsheetFile book=SpreadsheetFile.xlsx(zip(files));assertTrue(book.characters>100000);assertEquals(601,book.cells);assertEquals("First visible",book.sheets.get(0).name);assertEquals(3,book.sheets.get(0).columnCount);assertNull(book.sheets.get(0).cell(2,1));assertEquals("भारत ಭಾರತ",book.sheets.get(0).cell(2,3).value);assertEquals(600,book.sheets.get(1).rowCount);
    }
    @Test public void quotedCsvRetainsMultilineValuesAndNeverEvaluatesFormula()throws Exception{
        SpreadsheetFile book=SpreadsheetFile.csv("Name,Value\r\n\"two\nlines\",\"say \"\"yes\"\"\"\r\n=1+2,3\n");SpreadsheetFile.Sheet sheet=book.sheets.get(0);assertEquals(3,sheet.rowCount);assertEquals("two\nlines",sheet.cell(2,1).value);assertEquals("say \"yes\"",sheet.cell(2,2).value);assertEquals("=1+2",sheet.cell(3,1).value);
        try{SpreadsheetFile.csv("\"unfinished");fail("Malformed quotes must fail explicitly");}catch(IOException expected){}
    }
    @Test public void spreadsheetTraversalAndEntityDeclarationsFailClosed()throws Exception{
        Map<String,String> entries=new LinkedHashMap<>();entries.put("../escape.xml","untrusted");try{SpreadsheetFile.xlsx(zip(entries));fail("Traversal must be rejected before parsing");}catch(IOException expected){}
        entries.clear();entries.put("xl/_rels/workbook.xml.rels","<!DOCTYPE x [<!ENTITY y SYSTEM 'file:///private'>]><Relationships/>");try{SpreadsheetFile.xlsx(zip(entries));fail("Entity declarations must be rejected");}catch(IOException expected){}
    }
    @Test public void viewedIndexFindsRealEnglishAndIndicPrefixesAndClearingNeverTouchesOriginals()throws Exception{
        File root=new File(context().getCacheDir(),"viewed-index-test-"+UUID.randomUUID());assertTrue(root.mkdir());Context isolated=new ContextWrapper(context()){@Override public Context getApplicationContext(){return this;}@Override public File getFilesDir(){return root;}};
        File original=new File(root,"original.txt");java.nio.file.Files.write(original.toPath(),new byte[]{1,2,3});Uri uri=Uri.parse("content://com.android.externalstorage.documents/document/primary%3Aviewed-fixture.txt");
        try(ViewedFiles index=new ViewedFiles(isolated)){index.remember(uri,"Fixture","text/plain","notes भारत ಭಾರತ हिंदी 😊 %");assertEquals(1,index.search("not").size());assertEquals(1,index.search("ಭಾ").size());assertEquals(1,index.search("हिं").size());assertEquals(1,index.search("😊").size());assertEquals(1,index.search("%").size());assertEquals(0,index.search("missing").size());index.clearIndex();assertTrue(index.search("").isEmpty());assertArrayEquals(new byte[]{1,2,3},java.nio.file.Files.readAllBytes(original.toPath()));}finally{remove(root);}
    }
    @Test public void copyToSameDocumentRejectsBeforeOpeningAnythingForWrite()throws Exception{
        Uri uri=Uri.parse("content://com.android.externalstorage.documents/document/primary%3Anever-write-original.txt");try{ViewedFileCopy.write(context(),uri,uri);fail("Never truncate original URI");}catch(IOException expected){assertTrue(expected.getMessage().contains("different destination"));}
    }
    private void remove(File file){File[] children=file.listFiles();if(children!=null)for(File child:children)remove(child);file.delete();}
}
